from decimal import Decimal, InvalidOperation
from fractions import Fraction


def _decimal_to_fraction(weight: Decimal) -> Fraction:
    tup = weight.as_tuple()
    digits = tup.digits
    exp = tup.exponent
    if not digits:
        return Fraction(0, 1)
    int_digits = int(''.join(map(str, digits))) if digits else 0
    if tup.sign:
        return Fraction(0, 1)
    if exp >= 0:
        return Fraction(int_digits * (10 ** exp), 1)
    return Fraction(int_digits, 10 ** (-exp))


def allocate_by_ratios(total: str, ratios: list) -> list[Decimal]:
    if not isinstance(total, str):
        raise ValueError("total must be a string")
    try:
        amount = Decimal(total)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid total: {total!r}") from None
    if not amount.is_finite():
        raise ValueError("total must be finite")
    tup = amount.as_tuple()
    exp = tup.exponent
    digits = tup.digits
    # finite Decimal always has int exponent and non-empty digits
    if not isinstance(exp, int) or len(digits) == 0:
        raise ValueError("invalid total")
    int_digits = int(''.join(map(str, digits)))
    e = exp + 2
    if e >= 0:
        cents_abs = int_digits * (10 ** e)
    else:
        divisor = 10 ** (-e)
        if int_digits % divisor != 0:
            raise ValueError("total must have at most 2 decimal places")
        cents_abs = int_digits // divisor
    if not isinstance(ratios, list) or len(ratios) == 0:
        raise ValueError("ratios must be a non-empty list")
    weights_frac: list[Fraction] = []
    weights_dec: list[Decimal] = []
    for entry in ratios:
        if isinstance(entry, bool):
            raise ValueError("bool weights are not accepted")
        if isinstance(entry, int):
            weight = Decimal(entry)
        elif isinstance(entry, Decimal):
            weight = entry
        elif isinstance(entry, str):
            try:
                weight = Decimal(entry)
            except (InvalidOperation, ValueError):
                raise ValueError(f"invalid weight: {entry!r}") from None
        else:
            raise ValueError(f"invalid weight: {entry!r}")
        if not weight.is_finite():
            raise ValueError("weights must be finite")
        if weight < 0:
            raise ValueError("weights must be >= 0")
        weights_dec.append(weight)
        weights_frac.append(_decimal_to_fraction(weight))
    total_weight = sum(weights_frac, Fraction(0, 1))
    if total_weight <= 0:
        raise ValueError("at least one weight must be > 0")
    negative = amount < 0
    n = len(weights_frac)
    floors: list[int] = [0] * n
    remainders: list[Fraction] = [Fraction(0, 1)] * n
    for i, w in enumerate(weights_frac):
        if w == 0:
            floors[i] = 0
            remainders[i] = Fraction(0, 1)
        else:
            exact = Fraction(cents_abs, 1) * w / total_weight
            q = exact.numerator // exact.denominator
            floors[i] = q
            remainders[i] = exact - q
    remaining = cents_abs - sum(floors)
    order = sorted(
        (i for i, w in enumerate(weights_frac) if w > 0),
        key=lambda i: (-remainders[i], -weights_frac[i], i),
    )
    for i in order[:remaining]:
        floors[i] += 1
    parts: list[Decimal] = []
    for floor_cents in floors:
        part = Decimal(floor_cents).scaleb(-2)
        if negative and part != 0:
            part = -part
        parts.append(part)
    return parts
